"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");

const DATABASE_CONFIG = {
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
};
const MODEL_NAMES = {
  user: "User",
  article: "Article",
  comment: "Comment",
};
const FOREIGN_KEYS = {
  user: "userId",
  article: "articleId",
};
const ASSOCIATION_ALIASES = {
  author: "author",
};
const HIDDEN_ATTRIBUTES = {
  user: ["id", "updatedAt", "createdAt"],
  article: ["id", FOREIGN_KEYS.user],
  comment: [FOREIGN_KEYS.article, FOREIGN_KEYS.user],
};

const sequelize = new Sequelize(DATABASE_CONFIG);

function serializeWithout(model, hiddenAttributes) {
  const data = { ...model.get() };

  hiddenAttributes.forEach((attribute) => {
    delete data[attribute];
  });

  return data;
}

function modelOptions(modelName) {
  return { sequelize, modelName };
}

class User extends Model {
  static associate() {
    this.hasMany(Article, {
      foreignKey: FOREIGN_KEYS.user,
      onDelete: "CASCADE",
    });
    this.hasMany(Comment, { foreignKey: FOREIGN_KEYS.user });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.user);
  }
}

class Article extends Model {
  static associate() {
    this.belongsTo(User, {
      foreignKey: FOREIGN_KEYS.user,
      as: ASSOCIATION_ALIASES.author,
    });
    this.hasMany(Comment, {
      foreignKey: FOREIGN_KEYS.article,
      onDelete: "CASCADE",
    });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.article);
  }
}

class Comment extends Model {
  static associate() {
    this.belongsTo(Article, { foreignKey: FOREIGN_KEYS.article });
    this.belongsTo(User, {
      as: ASSOCIATION_ALIASES.author,
      foreignKey: FOREIGN_KEYS.user,
    });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.comment);
  }
}

function defineModels() {
  User.init(
    { username: DataTypes.STRING },
    modelOptions(MODEL_NAMES.user),
  );

  Article.init(
    { slug: DataTypes.STRING },
    modelOptions(MODEL_NAMES.article),
  );

  Comment.init(
    {
      id: {
        allowNull: false,
        autoIncrement: true,
        primaryKey: true,
        type: DataTypes.INTEGER,
      },
      body: DataTypes.TEXT,
    },
    modelOptions(MODEL_NAMES.comment),
  );
}

function associateModels() {
  User.associate();
  Article.associate();
  Comment.associate();
}

defineModels();
associateModels();

module.exports = {
  sequelize,
  User,
  Article,
  Comment,
  ASSOCIATION_ALIASES,
};

const { createApp } = require("./app");
const { sequelize } = require("./models");
const { seed } = require("./seed");

const PORT = 3001;

async function start() {
  try {
    await sequelize.sync({ alter: true });
    await seed();

    const app = createApp();
    app.listen(PORT, () =>
      console.log(`Server running on http://localhost:${PORT}`),
    );
  } catch (error) {
    console.error("Unable to start:", error);
    process.exit(1);
  }
}

if (require.main === module) {
  start();
}

module.exports = { start };

const { User, Article, Comment } = require("./models");

const SEED_USER = { username: "u1" };
const SEED_ARTICLE = { slug: "a1" };
const SEED_COMMENT_BODIES = ["c1", "c2"];

async function seed() {
  const [user] = await User.findOrCreate({
    where: SEED_USER,
    defaults: SEED_USER,
  });

  const [article] = await Article.findOrCreate({
    where: SEED_ARTICLE,
    defaults: { ...SEED_ARTICLE, userId: user.id },
  });

  const count = await Comment.count({ where: { articleId: article.id } });
  if (count > 0) {
    return;
  }

  const comments = SEED_COMMENT_BODIES.map((body) => ({
    body,
    articleId: article.id,
    userId: user.id,
  }));

  await Comment.bulkCreate(comments);
}

module.exports = { seed };

const { User, Article, ASSOCIATION_ALIASES } = require("./models");

const COMMENT_AUTHOR_INCLUDE = [
  { model: User, as: ASSOCIATION_ALIASES.author, attributes: ["username"] },
];
const ERROR_CODES = {
  notFound: "not_found",
  serverError: "server_error",
};

function registerRoutes(app) {
  app.get("/api/articles/:slug/comments", getArticleComments);
}

function sendNotFound(res) {
  return res.status(404).json({ error: ERROR_CODES.notFound });
}

function sendServerError(res, error) {
  console.error(error);
  return res.status(500).json({ error: ERROR_CODES.serverError });
}

async function getArticleComments(req, res) {
  try {
    const { slug } = req.params;
    const article = await Article.findOne({ where: { slug } });
    if (!article) {
      return sendNotFound(res);
    }

    const comments = await article.getComments({
      include: COMMENT_AUTHOR_INCLUDE,
    });

    res.json({ comments });
  } catch (error) {
    sendServerError(res, error);
  }
}

module.exports = { registerRoutes };

const SERVER_CONFIG = {
  port: 3001,
};

const DATABASE_CONFIG = {
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
};

const SEED_DATA = {
  user: { username: "u1" },
  article: { slug: "a1" },
  commentBodies: ["c1", "c2"],
};

const ERROR_CODES = {
  notFound: "not_found",
  serverError: "server_error",
};

module.exports = {
  SERVER_CONFIG,
  DATABASE_CONFIG,
  SEED_DATA,
  ERROR_CODES,
};

